//! Third-party attributions (SPEC 10.4) generated by `scripts/third_party.py`: the list shown
//! in Settings → About and the full license texts. Release builds ship them in the
//! `licenses/` resource; dev builds read `binaries/licenses/` (`scripts/gen-third-party`).

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;

pub const LISTING: &str = "third-party.json";
pub const NOTICES: &str = "THIRD-PARTY-NOTICES.txt";

/// The folder with the generated files.
pub fn licenses_dir(resource_dir: Option<PathBuf>) -> Option<PathBuf> {
    if cfg!(debug_assertions) {
        Some(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("binaries/licenses"))
    } else {
        resource_dir.map(|dir| dir.join("licenses"))
    }
}

/// The parsed `third-party.json` of `dir`.
pub fn read_listing(dir: &Path) -> Result<Value, String> {
    let path = dir.join(LISTING);
    let text = fs::read_to_string(&path)
        .map_err(|e| format!("third-party list not found ({}): {e}", path.display()))?;
    serde_json::from_str(&text).map_err(|e| format!("invalid third-party list: {e}"))
}

/// The notices file of `dir`, when it exists.
pub fn notices_path(dir: &Path) -> Result<PathBuf, String> {
    let path = dir.join(NOTICES);
    if path.is_file() {
        Ok(path)
    } else {
        Err(format!("third-party list not found ({})", path.display()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_dir(name: &str) -> PathBuf {
        let dir = std::env::temp_dir()
            .join(format!("tonalia-notices-{name}-{}", std::process::id()))
            .join("Licencias ✨");
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn reads_the_generated_listing() {
        let dir = temp_dir("read");
        fs::write(
            dir.join(LISTING),
            r#"{"version":1,"packages":[{"name":"serde","license":"MIT OR Apache-2.0"}]}"#,
        )
        .unwrap();
        let listing = read_listing(&dir).unwrap();
        assert_eq!(listing["packages"][0]["name"], "serde");
        fs::remove_dir_all(dir.parent().unwrap()).unwrap();
    }

    #[test]
    fn missing_or_broken_files_are_clear_errors() {
        let dir = temp_dir("missing");
        assert!(read_listing(&dir)
            .unwrap_err()
            .starts_with("third-party list not found"));
        assert!(notices_path(&dir)
            .unwrap_err()
            .starts_with("third-party list not found"));
        fs::write(dir.join(LISTING), "{").unwrap();
        assert!(read_listing(&dir)
            .unwrap_err()
            .starts_with("invalid third-party list"));
        fs::write(dir.join(NOTICES), "texts").unwrap();
        assert_eq!(notices_path(&dir).unwrap(), dir.join(NOTICES));
        fs::remove_dir_all(dir.parent().unwrap()).unwrap();
    }

    #[test]
    fn release_builds_use_the_resource_folder() {
        let dir = licenses_dir(Some(PathBuf::from(
            "/Applications/Tonalia.app/Contents/Resources",
        )));
        if cfg!(debug_assertions) {
            assert!(dir.unwrap().ends_with("binaries/licenses"));
        } else {
            assert_eq!(
                dir.unwrap(),
                PathBuf::from("/Applications/Tonalia.app/Contents/Resources/licenses")
            );
        }
    }
}
